 function toInput(o:OpportunityRecord):OpportunityInput{const {id:_i,sourceInquiryId:_s,version:_v,createdAt:_c,updatedAt:_u,organizationId:_o,contactId:_ct,...input}=o;void _i;void _s;void _v;void _c;void _u;void _o;void _ct;return {...input,checks:{...input.checks}}}
 function openExistingOpportunity(id:string){const o=opps.find(x=>x.id===id);setInquiryDialog(null);setConvertDialog(null);if(page!=='Opportunities')go('Opportunities');if(o)setModal({type:'opportunity',isNew:false,id:o.id,version:o.version,sourceInquiryId:o.sourceInquiryId,item:toInput(o)});else void reloadWorkflow()}
 async function persistOpportunity(e:React.FormEvent){e.preventDefault();if(modal?.type!=='opportunity'||modalSaving)return;setModalSaving(true);setModalError('');const r=modal.isNew||!modal.id?await wf.createOpportunity(modal.item):await wf.updateOpportunity(modal.id,modal.version??0,modal.item);setModalSaving(false);if(!r.ok){setModalError(r.status===409?'This opportunity changed in another window. Close and reopen it to load the latest version.':r.error);return}setModal(null);setMessage('Opportunity saved')}
 const modalField=(field:string,value:string|null|Record<string,string>)=>setModal(m=>m ? {...m,item:{...m.item,[field]:value}} as Modal : null);
