 {codeTab==='Product Service Codes'&&<section className="panel form-panel"><div className="panel-heading"><div><h2>Preferred PSC for planning</h2><p>A working preference only; each solicitation and deliverable needs its own PSC review.</p></div></div><div className="form-grid"><label className="field"><span>Working primary PSC</span><select value={w.primaryPsc||''} onChange={e=>edit(d=>d.primaryPsc=e.target.value)}><option value="">Not selected</option>{w.psc.map(c=><option key={c.code} value={c.code}>{c.code} — {c.title}</option>)}</select></label><Field label="PSC selection rationale" value={w.primaryPscReason||''} onChange={v=>edit(d=>d.primaryPscReason=v)}/></div></section>}
