 {page==='Annual receipts'&&<section className="panel form-panel"><div className="panel-heading"><div><h2>Annual receipts record</h2><p>No revenue figure is assumed. Enter a supported amount.</p></div><Status value={w.receipts.status} onChange={v=>edit(d=>d.receipts.status=v)}/></div><div className="notice">This record does not determine business size or eligibility. A form&apos;s annual receipts field and an SBA size-standard calculation may use different periods and rules. Verify the exact requirement before transferring figures.</div><div className="form-grid"><Field label="Annual receipts amount" type="number" value={w.receipts.amount} onChange={v=>edit(d=>d.receipts.amount=v)} placeholder="Enter amount"/><Field label="Currency" value={w.receipts.currency} onChange={v=>edit(d=>d.receipts.currency=v)}/><Field label="Fiscal year / measurement period" value={w.receipts.year} onChange={v=>edit(d=>d.receipts.year=v)} placeholder="e.g. FY 2025"/><Field label="Reviewer / accountant" value={w.receipts.reviewer} onChange={v=>edit(d=>d.receipts.reviewer=v)}/><Field area label="Worldwide entity and affiliate scope" value={w.receipts.scope} onChange={v=>edit(d=>d.receipts.scope=v)}/><Field area label="Calculation basis & supporting record references" value={w.receipts.basis} onChange={v=>edit(d=>d.receipts.basis=v)}/><Field area label="Assumptions, exclusions & review notes" value={w.receipts.notes} onChange={v=>edit(d=>d.receipts.notes=v)}/></div><div className="panel-foot"><Link href={sources.receipts}>13 CFR 121.104 receipts rules</Link><span>Confirm applicable period, affiliation treatment, and source documents.</span></div></section>}
